class Solution:
    def maxDepth(self, root: Optional[TreeNode]) -> int:
        def depthOf(node, target, d):
            if not node:
                return 0
            if node is target:
                return d
            return max(depthOf(node.left, target, d + 1), depthOf(node.right, target, d + 1))

        nodes, stack = [], [root]
        while stack:
            node = stack.pop()
            if node:
                nodes.append(node)
                stack.append(node.left)
                stack.append(node.right)
        best = 0
        for t in nodes:
            best = max(best, depthOf(root, t, 1))
        return best

