class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        rows, cols = len(grid), len(grid[0])
        label = [[r * cols + c if grid[r][c] == "1" else -1 for c in range(cols)] for r in range(rows)]
        changed = True
        while changed:
            changed = False
            for r in range(rows):
                for c in range(cols):
                    if label[r][c] < 0:
                        continue
                    for nr, nc in ((r + 1, c), (r, c + 1)):
                        if nr < rows and nc < cols and label[nr][nc] >= 0:
                            low = min(label[r][c], label[nr][nc])
                            if label[r][c] != low or label[nr][nc] != low:
                                label[r][c] = label[nr][nc] = low
                                changed = True
        return len({x for row in label for x in row if x >= 0})

