class Solution:
    def findPermutation(self, nums: List[int]) -> List[int]:
        n = len(nums)
        full = (1 << n) - 1

        @cache
        def dp(mask, last):
            if mask == full:
                return abs(last - nums[0])
            best = math.inf
            for nxt in range(n):
                if not mask >> nxt & 1:
                    best = min(best, abs(last - nums[nxt]) + dp(mask | 1 << nxt, nxt))
            return best

        perm, mask = [0], 1
        while mask != full:
            last = perm[-1]
            for nxt in range(n):
                if not mask >> nxt & 1 and abs(last - nums[nxt]) + dp(mask | 1 << nxt, nxt) == dp(mask, last):
                    perm.append(nxt)
                    mask |= 1 << nxt
                    break
        return perm

