        MOD = 10 ** 9 + 7
        dp = [1] + [0] * target  # mass per running sum
        for _ in range(n):
            new = [0] * (target + 1)
            for t in range(target + 1):
                if dp[t] == 0:
                    continue
                for f in range(1, k + 1):
                    if t + f <= target:
