class Solution:
    def countSmaller(self, nums: List[int]) -> List[int]:
        ranks = {v: i + 1 for i, v in enumerate(sorted(set(nums)))}
        m = len(ranks)
        tree = [0] * (m + 1)

        def update(i, delta):
            while i <= m:
                tree[i] += delta
                i += i & -i

        def query(i):
            total = 0
            while i > 0:
                total += tree[i]
                i -= i & -i
            return total

        res = [0] * len(nums)
        for i in range(len(nums) - 1, -1, -1):
            r = ranks[nums[i]]
            res[i] = query(r - 1)
            update(r, 1)
        return res

