        # 1. Count each value in a hash map
        count = {}
        for num in nums:
            count[num] = count.get(num, 0) + 1

        # 2. Put each value into bucket number count
        buckets = [[] for i in range(len(nums) + 1)]
        for num, freq in count.items():
            buckets[freq].append(num)

