class Solution:
    def threeSum(self, nums: List[int]) -> List[List[int]]:
        result = []
        nums.sort()

        # 1. Fix the first value a, moving left to right
        for i in range(len(nums)):
            a = nums[i]

            # a is the smallest value in a sorted triple, so if a > 0 no triple can sum to zero
            if a > 0:
                break

            # skip repeated values of a to avoid duplicate triples
            if i > 0 and a == nums[i - 1]:
                continue

            # 2. Two pointers on the rest of the array to find pairs summing to -a
            left = i + 1
            right = len(nums) - 1

            while left < right:
                total = a + nums[left] + nums[right]

                if total > 0:
                    right -= 1
                elif total < 0:
                    left += 1
                else:
                    # 3. Record the triple, then move both pointers inward
                    result.append([a, nums[left], nums[right]])
                    left += 1
                    right -= 1

                    # 4. Skip repeated left values to avoid duplicate triples
                    while left < right and nums[left] == nums[left - 1]:
                        left += 1

        return result

