class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        # 1. Keep lowest price seen so far
        lowest_price = prices[0]
        max_profit = 0

        for price in prices:
            # 2. New lower price? update lowest
            if price < lowest_price:
                lowest_price = price

            # 3. Profit if sold today = price - lowest
            profit_today = price - lowest_price

            # 4. Keep the maximum profit
            if profit_today > max_profit:
                max_profit = profit_today

        return max_profit

