        if len(s1) > len(s2):
            return False

        # 1. Count each character in s1 and in the first window of s2
        s1Count = [0] * 26
        windowCount = [0] * 26
        for i in range(len(s1)):
            s1Count[ord(s1[i]) - ord("a")] += 1
            windowCount[ord(s2[i]) - ord("a")] += 1

