            # 3. Add the new right character to the window
            rightIndex = ord(s2[right]) - ord("a")
            windowCount[rightIndex] += 1
            if windowCount[rightIndex] == s1Count[rightIndex]:
                matches += 1
            elif windowCount[rightIndex] == s1Count[rightIndex] + 1:
