class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if len(s) < len(t):
            return ""

        # 1. Count what t needs
        needCount = {}
        for c in t:
            needCount[c] = needCount.get(c, 0) + 1
        need = len(needCount)

        windowCount = {}
        have = 0
        left = 0
        bestLeft = -1
        bestRight = -1
        bestLength = float("infinity")

        for right in range(len(s)):
            # 2. Expand right; when a letter's count is met, have += 1
            c = s[right]
            windowCount[c] = windowCount.get(c, 0) + 1
            if c in needCount and windowCount[c] == needCount[c]:
                have += 1

            # 3. While valid, record window and shrink from the left
            while have == need:
                currentLength = right - left + 1
                if currentLength < bestLength:
                    bestLength = currentLength
                    bestLeft = left
                    bestRight = right

                leftChar = s[left]
                windowCount[leftChar] -= 1
                if leftChar in needCount and windowCount[leftChar] < needCount[leftChar]:
                    have -= 1
                left += 1

        # 4. Return the shortest recorded window
        if bestLength == float("infinity"):
            return ""
        return s[bestLeft:bestRight + 1]

