class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        stack = []
        for token in tokens:
            # 1. If token is an operator, pop the two most recent values
            if token == "+" or token == "-" or token == "*" or token == "/":
                second = stack.pop()
                first = stack.pop()
                # 2. Apply the operator in the correct order
                if token == "+":
                    result = first + second
                elif token == "-":
                    result = first - second
                elif token == "*":
                    result = first * second
                else:
                    result = int(float(first) / second)
                # 3. Push the result back onto the stack
                stack.append(result)
            else:
                # 4. If token is a number, push it onto the stack
                stack.append(int(token))
        return stack[0]

