class Solution:
    def carFleet(self, target: int, position: List[int], speed: List[int]) -> int:
        # 1. Pair each car's position with its speed
        cars = []
        for i in range(len(position)):
            cars.append((position[i], speed[i]))

        # 2. Sort cars by position, closest to target first
        cars.sort(reverse=True)

        # 3. Walk from the car nearest the target backward
        fleets = []
        for position_i, speed_i in cars:
            arrival_time = (target - position_i) / speed_i
            fleets.append(arrival_time)
            # 4. If this car catches up to the fleet ahead, merge it
            if len(fleets) >= 2 and fleets[-1] <= fleets[-2]:
                fleets.pop()

