        left = 0
        right = len(nums) - 1
        smallest_seen = float("inf")

        # 1. Shrink the search range using the middle and right end
        while left < right:
            mid = left + (right - left) // 2
            smallest_seen = min(smallest_seen, nums[mid])

            # 2. If mid is bigger than the right end, the minimum is to the right
            if nums[mid] > nums[right]:
                left = mid + 1
            # 3. Otherwise mid..end is sorted, so the minimum is mid or to the left
