class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        # 1. Make sure A is the smaller array so binary search is on the smaller one
        A, B = nums1, nums2
        if len(B) < len(A):
            A, B = B, A

        total = len(A) + len(B)
        half = total // 2

        left = 0
        right = len(A) - 1

        while True:
            # 2. Pick a cut i in A, then compute the matching cut j in B
            i = (left + right) // 2
            j = half - i - 2

            Aleft = float("-infinity")
            if i >= 0:
                Aleft = A[i]

            Aright = float("infinity")
            if i + 1 < len(A):
                Aright = A[i + 1]

            Bleft = float("-infinity")
            if j >= 0:
                Bleft = B[j]

            Bright = float("infinity")
            if j + 1 < len(B):
                Bright = B[j + 1]

            # 3. Check if this partition is valid
            if Aleft <= Bright and Bleft <= Aright:
                if total % 2 == 1:
                    return min(Aright, Bright)
                return (max(Aleft, Bleft) + min(Aright, Bright)) / 2
            elif Aleft > Bright:
                # 4. Too far right in A, move left
                right = i - 1
            else:
                # 4. Too far left in A, move right
                left = i + 1

