    def levelOrder(self, root: TreeNode) -> List[List[int]]:
        result = []
        queue = collections.deque()
        if root:
            queue.append(root)

        # 1. Keep going while there are nodes left to process
        while queue:
            level_size = len(queue)
            level_values = []

            # 2. Process exactly one level's worth of nodes
            for i in range(level_size):
