        result = []
        queue = collections.deque([root])

        # 1. BFS level by level
        while queue:
            level_size = len(queue)
            last_node = None

            # 2. Process every node in this level
            for i in range(level_size):
                node = queue.popleft()
                if node:
                    last_node = node
                    queue.append(node.left)
                    queue.append(node.right)

            # 3. The last real node popped is the rightmost one
            if last_node:
                result.append(last_node.val)

