class Solution:
    def isValidBST(self, root: TreeNode) -> bool:
        # 1. Helper checks that node's value fits in (left, right)
        def valid(node, left, right):
            # 2. An empty node is always valid
            if not node:
                return True

            # 3. Node must be strictly inside the open interval
            if not (left < node.val < right):
                return False

            # 4. Left subtree lowers upper bound, right subtree raises lower bound
            left_ok = valid(node.left, left, node.val)
            right_ok = valid(node.right, node.val, right)
            return left_ok and right_ok

        return valid(root, float("-inf"), float("inf"))

