class Solution:
    def maxPathSum(self, root: TreeNode) -> int:
        best = [root.val]

        # 1. DFS returns the best downward chain sum from this node
        def dfs(node):
            if not node:
                return 0

            # 2. Drop negative child chains, treat them as zero
            leftChain = max(dfs(node.left), 0)
            rightChain = max(dfs(node.right), 0)

            # 3. Record node + left + right as a bent path
            bentSum = node.val + leftChain + rightChain
            if bentSum > best[0]:
                best[0] = bentSum

            # 4. Return node + the larger chain to the parent
            return node.val + max(leftChain, rightChain)

        dfs(root)
        return best[0]

