            if not pre:
                return None
            node = TreeNode(pre[0])
            mid = ino.index(pre[0])
            node.left = build(pre[1 : mid + 1], ino[:mid])
            node.right = build(pre[mid + 1 :], ino[mid + 1 :])
            return node

        return build(pre, ino)

