class Solution:
    def leastInterval(self, tasks: List[str], n: int) -> int:
        # 1. Count how many times each task occurs
        counts = Counter(tasks)
        maxHeap = [-count for count in counts.values()]
        heapq.heapify(maxHeap)

        time = 0
        cooldownQueue = deque()  # holds [remainingCount, readyTime]

        # 2. Simulate time unit by unit
        while maxHeap or cooldownQueue:
            time += 1

            # 3. If no task is ready, jump ahead to the next ready time
            if not maxHeap:
                time = cooldownQueue[0][1]
            else:
                remainingCount = heapq.heappop(maxHeap) + 1
                if remainingCount < 0:
                    cooldownQueue.append([remainingCount, time + n])

            # 4. Bring back any task whose cooldown has ended
            if cooldownQueue and cooldownQueue[0][1] == time:
                heapq.heappush(maxHeap, cooldownQueue.popleft()[0])

        return time

