class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        rows = len(board)
        cols = len(board[0])
        path = set()

        # dfs tries to match word starting at index i from cell (row, col)
        def dfs(row, col, i):
            if i == len(word):
                return True
            if row < 0 or row >= rows or col < 0 or col >= cols:
                return False
            if (row, col) in path:
                return False
            if board[row][col] != word[i]:
                return False

            # mark this cell as used on the current path
            path.add((row, col))

            found = (
                dfs(row + 1, col, i + 1)
                or dfs(row - 1, col, i + 1)
                or dfs(row, col + 1, i + 1)
                or dfs(row, col - 1, i + 1)
            )

            # unmark on the way back so other paths can use this cell
            path.remove((row, col))
            return found

        # try every cell as a possible starting point
        for row in range(rows):
            for col in range(cols):
                if dfs(row, col, 0):
                    return True
        return False

