class Solution:
    def findWords(self, board: List[List[str]], words: List[str]) -> List[str]:
        # 1. Build a trie from all the words
        root = TrieNode()
        for word in words:
            root.add_word(word)

        rows = len(board)
        cols = len(board[0])
        found = set()
        visited = set()

        # 2. DFS from a cell, walking the board and the trie together
        def dfs(row, col, node, path):
            if row < 0 or row >= rows or col < 0 or col >= cols:
                return
            if (row, col) in visited:
                return
            letter = board[row][col]
            if letter not in node.children:
                return
            child = node.children[letter]
            if child.count < 1:
                return

            visited.add((row, col))
            path += letter

            # 3. Found a complete word: record it and remove it from the trie
            if child.is_word:
                child.is_word = False
                found.add(path)
                root.remove_word(path)

            dfs(row + 1, col, child, path)
            dfs(row - 1, col, child, path)
            dfs(row, col + 1, child, path)
            dfs(row, col - 1, child, path)

            visited.remove((row, col))

        # 4. Start a DFS from every cell on the board
        for row in range(rows):
            for col in range(cols):
                dfs(row, col, root, "")

        return list(found)

