from collections import deque

class Solution:
    def wallsAndGates(self, rooms: List[List[int]]) -> None:
        rows = len(rooms)
        cols = len(rooms[0])
        visited = set()
        queue = deque()

        # 1. Queue every gate and mark it visited
        for row in range(rows):
            for col in range(cols):
                if rooms[row][col] == 0:
                    queue.append((row, col))
                    visited.add((row, col))

        distance = 0
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        # 2. Pop a whole layer, writing the current distance into each cell
        while queue:
            layer_size = len(queue)
            for i in range(layer_size):
                row, col = queue.popleft()
                rooms[row][col] = distance

                # 3. Push unvisited, non-wall neighbours
                for row_offset, col_offset in directions:
                    next_row = row + row_offset
                    next_col = col + col_offset
                    if next_row < 0 or next_row == rows:
                        continue
                    if next_col < 0 or next_col == cols:
                        continue
                    if (next_row, next_col) in visited:
                        continue
                    if rooms[next_row][next_col] == -1:
                        continue
                    visited.add((next_row, next_col))
                    queue.append((next_row, next_col))

            # 4. Increase the distance after each layer
            distance += 1

