class Solution:
    def orangesRotting(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        cols = len(grid[0])
        queue = collections.deque()
        fresh_count = 0

        # 1. Count fresh oranges and queue every rotten one
        for row in range(rows):
            for col in range(cols):
                if grid[row][col] == 1:
                    fresh_count += 1
                if grid[row][col] == 2:
                    queue.append((row, col))

        minutes = 0
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        # 2. Process the queue one layer at a time
        while fresh_count > 0 and queue:
            layer_size = len(queue)
            for i in range(layer_size):
                row, col = queue.popleft()

                # 3. Rot each fresh neighbour and queue it
                for dr, dc in directions:
                    new_row = row + dr
                    new_col = col + dc
                    if new_row < 0 or new_row >= rows:
                        continue
                    if new_col < 0 or new_col >= cols:
                        continue
                    if grid[new_row][new_col] == 1:
                        grid[new_row][new_col] = 2
                        queue.append((new_row, new_col))
                        fresh_count -= 1

            # 4. Each finished layer adds one minute
            minutes += 1

        # 5. Fresh left over means impossible
        if fresh_count != 0:
            return -1
        return minutes

