class Solution:
    def pacificAtlantic(self, heights: List[List[int]]) -> List[List[int]]:
        rows = len(heights)
        cols = len(heights[0])
        pacific = set()
        atlantic = set()

        def dfs(row, col, visited, prevHeight):
            if row < 0 or row == rows or col < 0 or col == cols:
                return
            if (row, col) in visited:
                return
            if heights[row][col] < prevHeight:
                return
            visited.add((row, col))
            dfs(row + 1, col, visited, heights[row][col])
            dfs(row - 1, col, visited, heights[row][col])
            dfs(row, col + 1, visited, heights[row][col])
            dfs(row, col - 1, visited, heights[row][col])

        # 1. DFS uphill from the Pacific edges (top row and left column)
        for col in range(cols):
            dfs(0, col, pacific, heights[0][col])
        for row in range(rows):
            dfs(row, 0, pacific, heights[row][0])

        # 2. DFS uphill from the Atlantic edges (bottom row and right column)
        for col in range(cols):
            dfs(rows - 1, col, atlantic, heights[rows - 1][col])
        for row in range(rows):
            dfs(row, cols - 1, atlantic, heights[row][cols - 1])

        # 3. Collect cells reachable from both oceans
        result = []
        for row in range(rows):
            for col in range(cols):
                if (row, col) in pacific and (row, col) in atlantic:
                    result.append([row, col])

        # 4. Return the overlap
        return result

