class Solution:
    def validTree(self, n: int, edges: List[List[int]]) -> bool:
        if n == 0:
            return True

        # 1. Build an undirected adjacency list
        adjacency = {i: [] for i in range(n)}
        for node1, node2 in edges:
            adjacency[node1].append(node2)
            adjacency[node2].append(node1)

        visited = set()

        # 2. DFS from node 0, passing along the parent we came from
        def dfs(node, parent):
            if node in visited:
                return False
            visited.add(node)
            for neighbor in adjacency[node]:
                # 3. Skip the parent; any other visited neighbour means a cycle
                if neighbor == parent:
                    continue
                if not dfs(neighbor, node):
                    return False
            return True

        if not dfs(0, -1):
            return False

        # 4. Every node must have been visited
        return len(visited) == n

