    def countComponents(self, n: int, edges: List[List[int]]) -> int:
        # 1. Every node starts as its own parent, count starts at n
        parent = [i for i in range(n)]
        size = [1] * n
        count = n

        # 2. find: follow parents to the root, compressing the path
        def find(node):
            root = node
            while root != parent[root]:
                parent[root] = parent[parent[root]]
                root = parent[root]
            return root

        # 3. union: attach the smaller tree under the larger, return True if merged
        def union(node1, node2):
            root1 = find(node1)
            root2 = find(node2)
            if root1 == root2:
                return False
            if size[root1] < size[root2]:
                root1, root2 = root2, root1
            parent[root2] = root1
            size[root1] += size[root2]
            return True

        # 4. For each edge, union its endpoints and subtract 1 on a successful merge
        for node1, node2 in edges:
            if union(node1, node2):
                count -= 1

        return count

