        adj = collections.defaultdict(list)

        def connected(a, b, seen):
            if a == b:
                return True
            seen.add(a)
            for nxt in adj[a]:
                if nxt not in seen and connected(nxt, b, seen):
                    return True
            return False

        for a, b in edges:
            if a in adj and b in adj and connected(a, b, set()):
                return [a, b]
            adj[a].append(b)
            adj[b].append(a)
        return []

