class Solution:
    def findRedundantConnection(self, edges: List[List[int]]) -> List[int]:
        # 1. Every node starts as its own parent
        parent = [i for i in range(len(edges) + 1)]
        size = [1] * (len(edges) + 1)

        def find(node):
            root = node
            while root != parent[root]:
                root = parent[root]
            while node != root:
                nextNode = parent[node]
                parent[node] = root
                node = nextNode
            return root

        # 2. For each edge, find the root of both ends
        for nodeA, nodeB in edges:
            rootA = find(nodeA)
            rootB = find(nodeB)

            # 3. Same root means this edge closes a cycle
            if rootA == rootB:
                return [nodeA, nodeB]

            # 4. Different roots, union them, smaller tree under larger
            if size[rootA] >= size[rootB]:
                parent[rootB] = rootA
                size[rootA] += size[rootB]
            else:
                parent[rootA] = rootB
                size[rootB] += size[rootA]

        return []

