class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        if endWord not in wordList:
            return 0

        def oneApart(a, b):
            diff = 0
            for x, y in zip(a, b):
                if x != y:
                    diff += 1
            return diff == 1

        visit = set([beginWord])
        q = deque([(beginWord, 1)])
        while q:
            word, steps = q.popleft()
            if word == endWord:
                return steps
            for w in wordList:
                if w not in visit and oneApart(word, w):
                    visit.add(w)
                    q.append((w, steps + 1))
        return 0

