class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        if endWord not in wordList:
            return 0

        # 1. Bucket every word by each wildcard pattern it matches
        pattern_to_words = collections.defaultdict(list)
        wordList.append(beginWord)
        for word in wordList:
            for position in range(len(word)):
                pattern = word[:position] + "*" + word[position + 1:]
                pattern_to_words[pattern].append(word)

        # 2. BFS from beginWord, one level per ladder step
        seen = set()
        seen.add(beginWord)
        queue = deque([beginWord])
        length = 1

        while queue:
            level_size = len(queue)
            for i in range(level_size):
                word = queue.popleft()
                if word == endWord:
                    return length

                # 3. Neighbors are all words sharing a pattern with this word
                for position in range(len(word)):
                    pattern = word[:position] + "*" + word[position + 1:]
                    for neighbor in pattern_to_words[pattern]:
                        if neighbor not in seen:
                            seen.add(neighbor)
                            queue.append(neighbor)
            length += 1

        # 4. No path found
        return 0

