class Solution:
    def networkDelayTime(self, times: List[List[int]], n: int, k: int) -> int:
        # 1. Build adjacency list of edges
        graph = collections.defaultdict(list)
        for source, destination, weight in times:
            graph[source].append((destination, weight))

        # 2. Push the starting node with time 0
        minHeap = [(0, k)]
        visited = set()
        lastTime = 0

        # 3. Pop the earliest node, skip if already finalized
        while minHeap:
            currentTime, currentNode = heapq.heappop(minHeap)
            if currentNode in visited:
                continue
            visited.add(currentNode)
            lastTime = currentTime

            # 4. Push each unvisited neighbor with updated time
            for neighbor, edgeWeight in graph[currentNode]:
                if neighbor not in visited:
                    heapq.heappush(minHeap, (currentTime + edgeWeight, neighbor))

        # 5. Answer is the last time popped, if all nodes were visited
        if len(visited) == n:
            return lastTime
        return -1

