class Solution:
    def findItinerary(self, tickets: List[List[str]]) -> List[str]:
        tickets.sort()
        used = [False] * len(tickets)
        path = ["JFK"]

        def backtrack(src):
            if len(path) == len(tickets) + 1:
                return True
            for i, (a, b) in enumerate(tickets):
                if not used[i] and a == src:
                    used[i] = True
                    path.append(b)
                    if backtrack(b):
                        return True
                    used[i] = False
                    path.pop()
            return False

        backtrack("JFK")
        return path

