class Solution:
    def findItinerary(self, tickets: List[List[str]]) -> List[str]:
        # 1. Build sorted destination lists per airport
        destinations = {}
        for src, dst in tickets:
            if src not in destinations:
                destinations[src] = []
            destinations[src].append(dst)
        for airport in destinations:
            destinations[airport].sort()

        result = []

        # 2. DFS from JFK, always taking the smallest remaining ticket
        def dfs(airport):
            while airport in destinations and len(destinations[airport]) > 0:
                next_airport = destinations[airport][0]
                # 3. Remove each ticket as it is used
                destinations[airport].pop(0)
                dfs(next_airport)
            # 4. When an airport is out of tickets, append it to result
            result.append(airport)

        dfs("JFK")
        result.reverse()

        if len(result) != len(tickets) + 1:
            return []

        return result

