        N = len(points)
        inTree = [False] * N
        inTree[0] = True
        res = 0
        for _ in range(N - 1):
            best, bestJ = float("inf"), -1
            for i in range(N):
                if not inTree[i]:
                    continue
                for j in range(N):
                    if inTree[j]:
                        continue
                    d = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
                    if d < best:
                        best, bestJ = d, j
            inTree[bestJ] = True
            res += best
        return res

