class Solution:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        numPoints = len(points)

        # 1. Build adjacency list of all pairwise Manhattan distances
        adjacency = {}
        for i in range(numPoints):
            adjacency[i] = []
        for i in range(numPoints):
            x1, y1 = points[i]
            for j in range(i + 1, numPoints):
                x2, y2 = points[j]
                distance = abs(x1 - x2) + abs(y1 - y2)
                adjacency[i].append([distance, j])
                adjacency[j].append([distance, i])

        # 2. Prim's algorithm: start from point 0 with cost 0
        totalCost = 0
        visited = set()
        minHeap = [[0, 0]]

        while len(visited) < numPoints:
            # 3. Pop the cheapest edge; skip if it leads to a visited point
            cost, point = heapq.heappop(minHeap)
            if point in visited:
                continue

            totalCost += cost
            visited.add(point)

            # 4. Push edges from this point to all unvisited neighbors
            for neighborCost, neighbor in adjacency[point]:
                if neighbor not in visited:
                    heapq.heappush(minHeap, [neighborCost, neighbor])

        return totalCost

