class Solution:
    def swimInWater(self, grid: List[List[int]]) -> int:
        N = len(grid)

        def canReach(t):
            seen = set()
            stack = [(0, 0)]
            while stack:
                r, c = stack.pop()
                if r < 0 or c < 0 or r == N or c == N:
                    continue
                if (r, c) in seen or grid[r][c] > t:
                    continue
                if r == N - 1 and c == N - 1:
                    return True
                seen.add((r, c))
                stack.extend([(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)])
            return False

        t = grid[0][0]
        while not canReach(t):
            t += 1
        return t

