class Solution:
    def alienOrder(self, words: List[str]) -> str:
        # 1. Make a node for every letter
        adjacent = {}
        for word in words:
            for letter in word:
                adjacent[letter] = set()

        # 2. For each adjacent pair of words, find the first differing letters
        for i in range(len(words) - 1):
            firstWord = words[i]
            secondWord = words[i + 1]
            minLength = min(len(firstWord), len(secondWord))

            if len(firstWord) > len(secondWord) and firstWord[:minLength] == secondWord[:minLength]:
                return ""

            for j in range(minLength):
                if firstWord[j] != secondWord[j]:
                    adjacent[firstWord[j]].add(secondWord[j])
                    break

        # 3. DFS with cycle detection, building a post-order list
        state = {}  # letter -> "visiting" or "done"
        order = []
        hasCycle = False

        def dfs(letter):
            nonlocal hasCycle
            if letter in state:
                if state[letter] == "visiting":
                    hasCycle = True
                return

            state[letter] = "visiting"
            for neighbor in adjacent[letter]:
                dfs(neighbor)
                if hasCycle:
                    return

            state[letter] = "done"
            order.append(letter)

        for letter in adjacent:
            dfs(letter)
            if hasCycle:
                return ""

        # 4. Reverse the post-order to get the final alphabet order
        order.reverse()
        return "".join(order)

