class Solution:
    def findCheapestPrice(
        self, n: int, flights: List[List[int]], src: int, dst: int, k: int
    ) -> int:
        # 1. Start with src at cost 0, everything else unreachable
        prices = [float("inf")] * n
        prices[src] = 0

        # 2. Repeat k + 1 times, each round allows one more flight
        for round_number in range(k + 1):
            # 3. Copy prices so this round only adds one flight per path
            new_prices = prices.copy()

            for source, destination, cost in flights:
                if prices[source] == float("inf"):
                    continue
                new_cost = prices[source] + cost
                if new_cost < new_prices[destination]:
                    new_prices[destination] = new_cost

            prices = new_prices

        # 4. Return the cheapest price found, or -1 if unreachable
        if prices[dst] == float("inf"):
            return -1
        return prices[dst]

