class Solution:
    def minCostClimbingStairs(self, cost: List[int]) -> int:
        # 1. Append 0 for the top step
        cost.append(0)

        # 2. Walk backward from the third-last index
        index = len(cost) - 3
        while index >= 0:
            # 3. Cost to reach step i plus cheaper of next two steps
            cost[index] += min(cost[index + 1], cost[index + 2])
            index -= 1

        # 4. Answer: min of starting at step 0 or step 1
        return min(cost[0], cost[1])

