class Solution:
    def rob(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]

        def best(i, tookFirst):
            if i >= n:
                return 0
            if i == n - 1 and tookFirst:
                return 0
            take = nums[i] + best(i + 2, tookFirst or i == 0)
            skip = best(i + 1, tookFirst)
            return max(take, skip)

        return best(0, False)

