class Solution:
    def rob(self, nums: List[int]) -> int:
        # 1. Edge case: only one house, rob it
        if len(nums) == 1:
            return nums[0]

        # 2. Try all houses except the last one
        withoutLast = self.helper(nums[:-1])

        # 3. Try all houses except the first one
        withoutFirst = self.helper(nums[1:])

        # 4. Return the better of the two options
        return max(withoutLast, withoutFirst)

    def helper(self, houses):
        previous = 0
        current = 0

        for money in houses:
            newCurrent = max(previous + money, current)
