    def longestPalindrome(self, s: str) -> str:
        self.result = ""
        self.result_length = 0

        # 1. Try every index as a possible center
        for i in range(len(s)):
            self.expand(s, i, i)
            self.expand(s, i, i + 1)

        return self.result

    def expand(self, s, left, right):
        # 2. Grow outward while characters match
        while left >= 0 and right < len(s) and s[left] == s[right]:
            current_length = right - left + 1
            # 3. Record this palindrome if it is the longest so far
            if current_length > self.result_length:
                self.result = s[left:right + 1]
                self.result_length = current_length
            left -= 1
            right += 1

