class Solution:
    def numDecodings(self, s: str) -> int:
        # 1. dp[i] = number of ways to decode s[i:]; empty tail decodes one way
        length = len(s)
        dp = {length: 1}

        for i in range(length - 1, -1, -1):
            # 2. A leading zero at position i gives zero ways
            if s[i] == "0":
                dp[i] = 0
                continue

            # 3. Single digit decode: add ways from the next position
            ways = dp[i + 1]

            # 4. Two digit decode if it forms a number from 10 to 26
            if i + 1 < length:
                first_digit = s[i]
                second_digit = s[i + 1]
                if first_digit == "1" or (first_digit == "2" and second_digit in "0123456"):
                    ways += dp[i + 2]

            dp[i] = ways

        return dp[0]

