class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        # 1. dp[a] = fewest coins to make amount a, start at 'infinity'
        infinity = amount + 1
        dp = [infinity] * (amount + 1)
        dp[0] = 0

        # 2. Build up from amount 0 to amount
        for a in range(1, amount + 1):
            # 3. Try every coin as the last coin used
            for coin in coins:
                if a - coin >= 0:
                    candidate = 1 + dp[a - coin]
                    if candidate < dp[a]:
                        dp[a] = candidate

        # 4. Still infinity means no combination works
        if dp[amount] == infinity:
            return -1
        return dp[amount]

