        length = len(s)
        # dp[i] means the suffix starting at i is breakable
        dp = [False] * (length + 1)
        # the empty suffix is always breakable
        dp[length] = True

        # fill dp from the end of the string to the start
        for i in range(length - 1, -1, -1):
            for word in wordDict:
                end = i + len(word)
                if end <= length and s[i:end] == word:
                    # dp[i] copies dp[i + len(word)]
                    if dp[end]:
