class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        cache = {}

        def dfs(day, buying):
            # Base case: no more days left to trade
            if day >= len(prices):
                return 0
            if (day, buying) in cache:
                return cache[(day, buying)]

            # Option 1: do nothing today, move to next day in same state
            best = dfs(day + 1, buying)

            if buying:
                # Option 2: buy today, become selling tomorrow
                profit = dfs(day + 1, False) - prices[day]
                if profit > best:
                    best = profit
            else:
                # Option 2: sell today, then must cooldown one day
                profit = dfs(day + 2, True) + prices[day]
                if profit > best:
                    best = profit

            cache[(day, buying)] = best
            return best

        return dfs(0, True)

