    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        # 1. Cache results for each (index, running total) pair
        cache = {}

        def backtrack(index, total):
            # 2. Base case: used all numbers, check if total matches target
            if index == len(nums):
                if total == target:
                    return 1
                else:
                    return 0

            if (index, total) in cache:
                return cache[(index, total)]

            # 3. Try adding the number and subtracting the number
            add_ways = backtrack(index + 1, total + nums[index])
            subtract_ways = backtrack(index + 1, total - nums[index])

            # 4. Store and return the total ways from this state
            cache[(index, total)] = add_ways + subtract_ways
            return cache[(index, total)]

        return backtrack(0, 0)

