class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        rows = len(matrix)
        cols = len(matrix[0])
        dp = {}

        # dfs returns the longest increasing path starting at (row, col)
        def dfs(row, col, prevVal):
            # off grid or not strictly increasing: dead end
            if row < 0 or row == rows or col < 0 or col == cols:
                return 0
            if matrix[row][col] <= prevVal:
                return 0
            if (row, col) in dp:
                return dp[(row, col)]

            # try all four directions, take the best
            best = 1
            down = 1 + dfs(row + 1, col, matrix[row][col])
            up = 1 + dfs(row - 1, col, matrix[row][col])
            right = 1 + dfs(row, col + 1, matrix[row][col])
            left = 1 + dfs(row, col - 1, matrix[row][col])
            best = max(best, down, up, right, left)

            dp[(row, col)] = best
            return best

        # run dfs from every cell, cache results, take the max
        longest = 0
        for row in range(rows):
            for col in range(cols):
                length = dfs(row, col, -1)
                longest = max(longest, length)
        return longest

