    def minDistance(self, word1: str, word2: str) -> int:
        length1 = len(word1)
        length2 = len(word2)

        # 1. Create grid of size (length1+1) x (length2+1)
        dp = [[0] * (length2 + 1) for i in range(length1 + 1)]

        # 2. Last row and column: remaining length
        for j in range(length2 + 1):
            dp[length1][j] = length2 - j
        for i in range(length1 + 1):
            dp[i][length2] = length1 - i

        # 3. Fill grid from bottom-right to top-left
