class Solution:
    def maxCoins(self, nums: List[int]) -> int:
        # 1. Pad the array with walls of value 1 on both ends
        balloons = [1] + nums + [1]
        size = len(balloons)
        best = {}

        # 2. Grow the interval width from 2 up to the full array
        for width in range(2, size):
            for left in range(size - width):
                right = left + width

                # 3. Try each pivot as the last balloon burst in this interval
                best_for_interval = 0
                for pivot in range(left + 1, right):
                    coins = balloons[left] * balloons[pivot] * balloons[right]
                    coins += best.get((left, pivot), 0)
                    coins += best.get((pivot, right), 0)
                    if coins > best_for_interval:
                        best_for_interval = coins

                # 4. Store the best result for this interval
                best[(left, right)] = best_for_interval

        return best.get((0, size - 1), 0)

