class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        string_length = len(s)
        pattern_length = len(p)

        # 1. cache[i][j] = does s[i:] match p[j:]?
        cache = [[False] * (pattern_length + 1) for i in range(string_length + 1)]

        # 2. Base case: both empty strings match
        cache[string_length][pattern_length] = True

        for i in range(string_length, -1, -1):
            for j in range(pattern_length - 1, -1, -1):
                char_matches = i < string_length and (s[i] == p[j] or p[j] == ".")

                # 3. Star next: skip the pair, or match one char and stay on j
                if j + 1 < pattern_length and p[j + 1] == "*":
                    cache[i][j] = cache[i][j + 2]
                    if char_matches:
                        cache[i][j] = cache[i][j] or cache[i + 1][j]
                # 4. Else: char match and cache[i+1][j+1]
                elif char_matches:
                    cache[i][j] = cache[i + 1][j + 1]

        return cache[0][0]

