class Solution:
    def maxSubArray(self, nums: List[int]) -> int:
        # 1. Start with the first number as the best answer so far
        best_sum = nums[0]

        # 2. Keep a running total as we scan the list
        running_total = 0
        for num in nums:
            running_total += num

            # 3. Update the best answer if the running total is bigger
            if running_total > best_sum:
                best_sum = running_total

            # 4. A negative running total only hurts future sums, so reset it
            if running_total < 0:
                running_total = 0

        return best_sum

