class Solution:
    def isNStraightHand(self, hand: List[int], groupSize: int) -> bool:
        # 1. Count each value
        if len(hand) % groupSize != 0:
            return False

        count = {}
        for card in hand:
            count[card] = count.get(card, 0) + 1

        # 2. Min-heap of distinct values
        minHeap = list(count.keys())
        heapq.heapify(minHeap)

        # 3. From the minimum, take one of each next value
        while minHeap:
            start = minHeap[0]
            for value in range(start, start + groupSize):
                if value not in count or count[value] == 0:
                    return False
                count[value] -= 1

                # 4. A value hitting zero must be the heap minimum
                if count[value] == 0:
                    if value != minHeap[0]:
                        return False
                    heapq.heappop(minHeap)

        return True

