class Solution:
    def checkValidString(self, s: str) -> bool:
        # 1. Track the range of possible open-bracket counts
        min_open = 0
        max_open = 0

        for c in s:
            # 2. Update the range based on the current character
            if c == "(":
                min_open = min_open + 1
                max_open = max_open + 1
            elif c == ")":
                min_open = min_open - 1
                max_open = max_open - 1
            else:
                min_open = min_open - 1
                max_open = max_open + 1

            # 3. If even the max count goes negative, no choice can work
            if max_open < 0:
                return False

            # 4. The min count can never go below zero
            if min_open < 0:
                min_open = 0

        return min_open == 0

