import heapq

class Solution:
    def minInterval(self, intervals: List[List[int]], queries: List[int]) -> List[int]:
        # 1. Sort intervals and queries
        intervals.sort()
        sortedQueries = sorted(queries)

        minHeap = []
        answerForQuery = {}
        intervalIndex = 0

        for query in sortedQueries:
            # 2. Push every interval that starts at or before this query
            while intervalIndex < len(intervals) and intervals[intervalIndex][0] <= query:
                left = intervals[intervalIndex][0]
                right = intervals[intervalIndex][1]
                size = right - left + 1
                heapq.heappush(minHeap, (size, right))
                intervalIndex += 1

            # 3. Remove intervals from the top that already ended before this query
            while minHeap and minHeap[0][1] < query:
                heapq.heappop(minHeap)

            # 4. The smallest valid interval is now at the top of the heap
            if minHeap:
                answerForQuery[query] = minHeap[0][0]
            else:
                answerForQuery[query] = -1

        # 5. Map answers back to the original order of queries
        result = []
        for query in queries:
            result.append(answerForQuery[query])
        return result

