class Solution:
    def plusOne(self, digits: List[int]) -> List[int]:
        # 1. Reverse so the ones digit comes first
        digits = digits[::-1]
        carry = 1
        index = 0

        while carry == 1:
            if index < len(digits):
                # 2. Nine? set to 0, keep the carry
                if digits[index] == 9:
                    digits[index] = 0
                else:
                    # 3. Otherwise add one and clear the carry
                    digits[index] += 1
                    carry = 0
            else:
                # 4. Ran out of digits with a carry? append 1
                digits.append(1)
                carry = 0
            index += 1

        return digits[::-1]

