class Solution:
    def myPow(self, x: float, n: int) -> float:
        def helper(base, exponent):
            # 1. Base cases: zero base or zero exponent
            if base == 0:
                return 0
            if exponent == 0:
                return 1

            # 2. Recurse on base squared with half the exponent
            half_result = helper(base * base, exponent // 2)

            # 3. If exponent is odd, multiply by one extra base
            if exponent % 2 == 1:
                return base * half_result
            return half_result

        # 4. Handle negative exponent by taking reciprocal
        result = helper(x, abs(n))
        if n >= 0:
            return result
        return 1 / result

