class Solution:
    def getSum(self, a: int, b: int) -> int:
        mask = 0xFFFFFFFF

        # 1. Keep adding without carry until there is no carry left
        while b & mask != 0:
            partial_sum = (a ^ b) & mask
            carry = ((a & b) << 1) & mask
            a = partial_sum
            b = carry

        # 2. If the result looks negative in 32-bit form, convert it back
        if a & 0x80000000:
            a = ~(a ^ mask)

        return a

