class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        def count_pieces(cap):
            # Greedily count how many pieces are needed if no piece sum exceeds cap
            pieces = 1
            current_sum = 0
            for num in nums:
                if current_sum + num > cap:
                    pieces += 1
                    current_sum = 0
                current_sum += num
            return pieces

        # 1. Search range: smallest possible cap is max(nums), largest is sum(nums)
        left = max(nums)
        right = sum(nums)

        # 2. Binary search on the cap value
        while left < right:
            mid = (left + right) // 2
            needed_pieces = count_pieces(mid)

            # 3. If this cap works, try a smaller cap
            if needed_pieces <= k:
                right = mid
            # 4. Otherwise, this cap is too small, try a bigger one
            else:
                left = mid + 1

        return left

