class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        def pieces(cap):
            count, run = 1, 0
            for x in nums:
                if run + x > cap:
                    count += 1
                    run = 0
                run += x
            return count

        lo, hi = max(nums), sum(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if pieces(mid) <= k:
                hi = mid
            else:
                lo = mid + 1
        return lo

