        diffs = {0}
        for r in range(R):
            for c in range(C):
                if r + 1 < R: diffs.add(abs(heights[r][c] - heights[r + 1][c]))
                if c + 1 < C: diffs.add(abs(heights[r][c] - heights[r][c + 1]))
