class Solution:
    def longestSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 2:
            return n
        left = [1] * n
        right = [1] * n
        for i in range(1, n):
            if nums[i - 1] <= nums[i]:
                left[i] = left[i - 1] + 1
        for i in range(n - 2, -1, -1):
            if nums[i] <= nums[i + 1]:
                right[i] = right[i + 1] + 1
        best = max(left)
        for i in range(n):
            if i > 0:
                best = max(best, left[i - 1] + 1)
            if i < n - 1:
                best = max(best, right[i + 1] + 1)
            if 0 < i < n - 1 and nums[i - 1] <= nums[i + 1]:
                best = max(best, left[i - 1] + 1 + right[i + 1])
        return best

