class Solution:
    def largestIsland(self, grid: List[List[int]]) -> int:
        n = len(grid)
        island_size = {}

        # 1. DFS each island, painting it with a unique label and recording its size
        def paint(row, col, label):
            if row < 0 or col < 0 or row == n or col == n:
                return 0
            if grid[row][col] != 1:
                return 0
            grid[row][col] = label
            count = 1
            count += paint(row + 1, col, label)
            count += paint(row - 1, col, label)
            count += paint(row, col + 1, label)
            count += paint(row, col - 1, label)
            return count

        label = 2
        for row in range(n):
            for col in range(n):
                if grid[row][col] == 1:
                    island_size[label] = paint(row, col, label)
                    label += 1

        # 2. Track the best answer seen so far (in case the grid is all land)
        best = 0
        for size in island_size.values():
            if size > best:
                best = size

        # 3. For each water cell, collect the distinct neighboring island ids
        for row in range(n):
            for col in range(n):
                if grid[row][col] == 0:
                    neighbor_ids = set()
                    neighbors = [(row + 1, col), (row - 1, col), (row, col + 1), (row, col - 1)]
                    for nr, nc in neighbors:
                        if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] > 1:
                            neighbor_ids.add(grid[nr][nc])

                    # 4. Candidate answer is 1 (flipped cell) plus sizes of distinct neighbor islands
                    total = 1
                    for island_id in neighbor_ids:
                        total += island_size[island_id]
                    if total > best:
                        best = total

        return best

