class Solution:
    def longestSubarray(self, nums: List[int], limit: int) -> int:
        maxq, minq = collections.deque(), collections.deque()
        left = best = 0
        for right, x in enumerate(nums):
            while maxq and maxq[-1] < x:
                maxq.pop()
            maxq.append(x)
            while minq and minq[-1] > x:
                minq.pop()
            minq.append(x)
            while maxq[0] - minq[0] > limit:
                if maxq[0] == nums[left]:
                    maxq.popleft()
                if minq[0] == nums[left]:
                    minq.popleft()
                left += 1
            best = max(best, right - left + 1)
        return best

