class Solution:
    def oddEvenJumps(self, arr: List[int]) -> int:
        n = len(arr)
        def next_jump(order):
            nxt = [None] * n
            stack = []
            for i in order:
                while stack and stack[-1] < i:
                    nxt[stack.pop()] = i
                stack.append(i)
            return nxt
        up = next_jump(sorted(range(n), key=lambda i: (arr[i], i)))
        down = next_jump(sorted(range(n), key=lambda i: (-arr[i], i)))
        odd, even = [False] * n, [False] * n
        odd[n - 1] = even[n - 1] = True
        for i in range(n - 2, -1, -1):
            if up[i] is not None:
                odd[i] = even[up[i]]
            if down[i] is not None:
                even[i] = odd[down[i]]
        return sum(odd)

