class Solution:
    def accountsMerge(self, accounts: List[List[str]]) -> List[List[str]]:
        parent = list(range(len(accounts)))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY

        # 1. Map each email to the first account that had it
        owner = {}
        for i in range(len(accounts)):
            emails = accounts[i][1:]
            for email in emails:
                if email in owner:
                    # 2. Seen before? Union this account with that owner
                    union(i, owner[email])
                else:
                    owner[email] = i

        # 3. Group emails by their owner's root
        groups = collections.defaultdict(list)
        for email in owner:
            i = owner[email]
            root = find(i)
            groups[root].append(email)

        # 4. Output name plus sorted emails per group
        result = []
        for root in groups:
            name = accounts[root][0]
            emails = sorted(groups[root])
            result.append([name] + emails)
        return result

