class Solution:
    def minimumWeight(self, n: int, edges: List[List[int]], src1: int, src2: int, dest: int) -> int:
        fwd = [[] for _ in range(n)]
        rev = [[] for _ in range(n)]
        for u, v, w in edges:
            fwd[u].append((v, w))
            rev[v].append((u, w))

        def dijkstra(src, adj):
            dist = [math.inf] * n
            dist[src] = 0
            heap = [(0, src)]
            while heap:
                d, u = heapq.heappop(heap)
                if d > dist[u]:
                    continue
                for v, w in adj[u]:
                    if d + w < dist[v]:
                        dist[v] = d + w
                        heapq.heappush(heap, (dist[v], v))
            return dist

        a, b, c = dijkstra(src1, fwd), dijkstra(src2, fwd), dijkstra(dest, rev)
        best = min(a[v] + b[v] + c[v] for v in range(n))
        return best if best < math.inf else -1

