import bisect

class SnapshotArray:

    def __init__(self, length: int):
        # 1. Each index starts with history [(-1, 0)]
        self.history = []
        for i in range(length):
            self.history.append([(-1, 0)])
        self.current_snap_id = 0

    def set(self, index: int, val: int) -> None:
        # 2. Overwrite if already changed in this snapshot, else append
        last_snap_id, last_val = self.history[index][-1]
        if last_snap_id == self.current_snap_id:
            self.history[index][-1] = (self.current_snap_id, val)
        else:
            self.history[index].append((self.current_snap_id, val))

    def snap(self) -> int:
        # 3. Return current snap id, then increment for next snapshot
        result = self.current_snap_id
        self.current_snap_id += 1
        return result

    def get(self, index: int, snap_id: int) -> int:
        # 4. Binary search for the last change at or before snap_id
        history_for_index = self.history[index]
        position = bisect.bisect_right(history_for_index, (snap_id, float('inf'))) - 1
        return history_for_index[position][1]

