        m, n = len(heightMap), len(heightMap[0])
        seen = [[False] * n for _ in range(m)]
        heap = []
        for r in range(m):
            for c in range(n):
                if r in (0, m - 1) or c in (0, n - 1):
                    heapq.heappush(heap, (heightMap[r][c], r, c))
                    seen[r][c] = True
        water = 0
        while heap:
            h, r, c = heapq.heappop(heap)
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
