from collections import deque, defaultdict
from typing import List

class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        # 1. Track what supplies we already have
        have = set(supplies)

        # 2. For each recipe, count how many ingredients are still missing
        missing_count = {}
        waiting_on = defaultdict(list)
        for i in range(len(recipes)):
            recipe = recipes[i]
            needed = ingredients[i]
            missing_count[recipe] = 0
            for ingredient in needed:
                if ingredient not in have:
                    missing_count[recipe] += 1
                    waiting_on[ingredient].append(recipe)

        # 3. Start with recipes that have no missing ingredients
        queue = deque()
        for recipe in recipes:
            if missing_count[recipe] == 0:
                queue.append(recipe)

        # 4. Cook recipes and unlock recipes waiting on them
        result = []
        while queue:
            current = queue.popleft()
            result.append(current)
            for next_recipe in waiting_on[current]:
                missing_count[next_recipe] -= 1
                if missing_count[next_recipe] == 0:
                    queue.append(next_recipe)

        return result

