    def minStartingIndex(self, s: str, pattern: str) -> int:
        def z_function(t):
            z = [0] * len(t)
            l = r = 0
            for i in range(1, len(t)):
                if i < r:
                    z[i] = min(r - i, z[i - l])
                while i + z[i] < len(t) and t[z[i]] == t[i + z[i]]:
                    z[i] += 1
                if i + z[i] > r:
                    l, r = i, i + z[i]
            return z

        m, n = len(pattern), len(s)
        pre = z_function(pattern + s)
        suf = z_function(pattern[::-1] + s[::-1])
        for i in range(n - m + 1):
            if pre[m + i] + suf[n - i] >= m - 1:
                return i
        return -1

