class MKAverage:
    def __init__(self, m: int, k: int):
        # 1. Store parameters and set up Fenwick trees over the value range
        self.m = m
        self.k = k
        self.max_value = 100000
        self.count_tree = [0] * (self.max_value + 1)
        self.sum_tree = [0] * (self.max_value + 1)
        self.window = collections.deque()

    def _update(self, value, delta):
        # Add delta count of 'value' into both Fenwick trees
        index = value
        while index <= self.max_value:
            self.count_tree[index] += delta
            self.sum_tree[index] += delta * value
            index += index & (-index)

    def _sum_of_smallest(self, target_count):
        # 2. Binary lift down the Fenwick tree to find the sum of the smallest 'target_count' values
        position = 0
        total_sum = 0
        remaining = target_count
        step = 1
        while step * 2 <= self.max_value:
            step *= 2
        while step > 0:
            next_position = position + step
            if next_position <= self.max_value and self.count_tree[next_position] < remaining:
                position = next_position
                remaining -= self.count_tree[next_position]
                total_sum += self.sum_tree[next_position]
            step //= 2
        return total_sum + remaining * (position + 1)

    def addElement(self, num: int) -> None:
        # 3. Keep the queue holding only the last m values seen
        self.window.append(num)
        self._update(num, 1)
        if len(self.window) > self.m:
            oldest = self.window.popleft()
            self._update(oldest, -1)

    def calculateMKAverage(self) -> int:
        if len(self.window) < self.m:
            return -1
        # 4. Middle sum = sum of smallest (m - k) values minus sum of smallest k values
        middle_sum = self._sum_of_smallest(self.m - self.k) - self._sum_of_smallest(self.k)
        return middle_sum // (self.m - 2 * self.k)

