class MKAverage:
    def __init__(self, m: int, k: int):
        self.m, self.k = m, k
        self.size = 100000
        self.cnt = [0] * (self.size + 1)
        self.tot = [0] * (self.size + 1)
        self.q = collections.deque()

    def _update(self, x, c):
        i = x
        while i <= self.size:
            self.cnt[i] += c
            self.tot[i] += c * x
            i += i & -i

    def _smallest(self, t):
        pos, s = 0, 0
        step = 1 << 16
        while step:
            nxt = pos + step
            if nxt <= self.size and self.cnt[nxt] < t:
                pos = nxt
                t -= self.cnt[nxt]
                s += self.tot[nxt]
            step >>= 1
        return s + t * (pos + 1)

    def addElement(self, num: int) -> None:
        self.q.append(num)
        self._update(num, 1)
        if len(self.q) > self.m:
            self._update(self.q.popleft(), -1)

    def calculateMKAverage(self) -> int:
        if len(self.q) < self.m:
            return -1
        mid = self._smallest(self.m - self.k) - self._smallest(self.k)
        return mid // (self.m - 2 * self.k)

