class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        NEG = float('-inf')
        EMPTY = (0, NEG, NEG, NEG)

        def leaf(v):
            return (v, v, v, v)

        def merge(a, b):
            return (a[0] + b[0], max(a[1], a[0] + b[1]),
                    max(b[2], b[0] + a[2]), max(a[3], b[3], a[2] + b[1]))

        size = 1
        while size < len(nums):
            size *= 2
        tree = [EMPTY] * (2 * size)
        for i, v in enumerate(nums):
            tree[size + i] = leaf(v)
        for i in range(size - 1, 0, -1):
            tree[i] = merge(tree[2 * i], tree[2 * i + 1])

        def update(i, node):
            i += size
            tree[i] = node
            while i > 1:
                i //= 2
                tree[i] = merge(tree[2 * i], tree[2 * i + 1])

        positions = collections.defaultdict(list)
        for i, v in enumerate(nums):
            positions[v].append(i)
        best = tree[1][3]
        for x, idxs in positions.items():
            if len(idxs) == len(nums):
                continue
            for i in idxs:
                update(i, EMPTY)
            best = max(best, tree[1][3])
            for i in idxs:
                update(i, leaf(x))
        return best

