class Solution:
    def subsequencePairCount(self, nums: List[int]) -> int:
        MOD = 10 ** 9 + 7
        dp = {(0, 0): 1}
        for x in nums:
            nxt = collections.defaultdict(int)
            for (a, b), ways in dp.items():
                for key in ((a, b), (math.gcd(a, x), b), (a, math.gcd(b, x))):
                    nxt[key] = (nxt[key] + ways) % MOD
