class Solution:
    def shortestSuperstring(self, words: List[str]) -> str:
        n = len(words)
        ov = [[0] * n for _ in range(n)]
        for i, a in enumerate(words):
            for j, b in enumerate(words):
                if i != j:
                    for k in range(min(len(a), len(b)), 0, -1):
                        if a.endswith(b[:k]):
                            ov[i][j] = k
                            break
        full = (1 << n) - 1
        dp = [[0] * n for _ in range(1 << n)]
        nxt = [[-1] * n for _ in range(1 << n)]
        for mask in range(1, full + 1):
            for i in range(n):
                rest = mask ^ (1 << i)
                if not mask >> i & 1 or not rest:
                    continue
                for j in range(n):
                    if rest >> j & 1 and (nxt[mask][i] == -1 or ov[i][j] + dp[rest][j] > dp[mask][i]):
                        dp[mask][i] = ov[i][j] + dp[rest][j]
                        nxt[mask][i] = j
        i = max(range(n), key=lambda s: dp[full][s])
        res, mask = words[i], full
        while nxt[mask][i] != -1:
            j = nxt[mask][i]
            res += words[j][ov[i][j]:]
            mask ^= 1 << i
            i = j
        return res

