from collections import defaultdict, OrderedDict

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.values = {}
        self.frequencies = {}
        self.groups = defaultdict(OrderedDict)
        self.minFreq = 0

    def _touch(self, key):
        # Move key from its current frequency group to the next one
        oldFreq = self.frequencies[key]
        del self.groups[oldFreq][key]
        if not self.groups[oldFreq] and self.minFreq == oldFreq:
            self.minFreq += 1
        newFreq = oldFreq + 1
        self.frequencies[key] = newFreq
        self.groups[newFreq][key] = None

    def get(self, key: int) -> int:
        if key not in self.values:
            return -1
        self._touch(key)
        return self.values[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return

        # 1. If the key already exists, update value and bump frequency
        if key in self.values:
            self.values[key] = value
            self._touch(key)
            return

        # 2. If cache is full, evict the oldest key in the min frequency group
        if len(self.values) == self.capacity:
            oldestKey, _ = self.groups[self.minFreq].popitem(last=False)
            del self.values[oldestKey]
            del self.frequencies[oldestKey]

        # 3. Insert the new key with frequency 1
        self.values[key] = value
        self.frequencies[key] = 1
        self.groups[1][key] = None
        self.minFreq = 1

