class Solution:
    def longestRepeating(self, s: str, queryCharacters: str, queryIndices: List[int]) -> List[int]:
        chars, n = list(s), len(s)
        pre, suf, best = [0] * (4 * n), [0] * (4 * n), [0] * (4 * n)

        def pull(node, lo, hi):
            mid = (lo + hi) // 2
            L, R = 2 * node, 2 * node + 1
            pre[node], suf[node] = pre[L], suf[R]
            best[node] = max(best[L], best[R])
            if chars[mid] == chars[mid + 1]:
                if pre[L] == mid - lo + 1:
                    pre[node] += pre[R]
                if suf[R] == hi - mid:
                    suf[node] += suf[L]
                best[node] = max(best[node], suf[L] + pre[R])

        def update(node, lo, hi, i):
            if lo == hi:
                pre[node] = suf[node] = best[node] = 1
                return
            mid = (lo + hi) // 2
            if i < 0 or i <= mid:
                update(2 * node, lo, mid, i)
            if i < 0 or i > mid:
                update(2 * node + 1, mid + 1, hi, i)
            pull(node, lo, hi)

        update(1, 0, n - 1, -1)
        out = []
        for c, i in zip(queryCharacters, queryIndices):
            chars[i] = c
            update(1, 0, n - 1, i)
            out.append(best[1])
        return out

