class Solution:
    def minimumCost(self, n: int, edges: List[List[int]], query: List[List[int]]) -> List[int]:
        parent = list(range(n))
        cost = [-1] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for u, v, w in edges:
            ru, rv = find(u), find(v)
            cost[rv] &= cost[ru] & w
            parent[ru] = rv
        res = []
        for s, t in query:
            rs, rt = find(s), find(t)
            res.append(cost[rs] if rs == rt else -1)
        return res

