                if x > y:
                    T[m + y][x] = 1

        def mul(A, B):
            C = [[0] * size for _ in range(size)]
            for i in range(size):
                for k in range(size):
                    if A[i][k]:
                        for j in range(size):
                            C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
            return C

        vec = list(range(m)) + [m - 1 - x for x in range(m)]
        p = n - 2
        while p:
            if p & 1:
                vec = [sum(T[i][j] * vec[j] for j in range(size)) % MOD for i in range(size)]
