        rest = t
        for p in (2, 3, 5, 7):
            while rest % p == 0:
                rest //= p
        if rest > 1:
            return "-1"

        def digits_for(r):
            out = []
            for d in range(9, 1, -1):
                while r % d == 0:
                    out.append(str(d))
                    r //= d
            return "".join(sorted(out))

        n = len(num)
        need = [t]
        for ch in num:
            if ch == "0":
                break
            need.append(need[-1] // gcd(need[-1], int(ch)))
        if len(need) == n + 1 and need[n] == 1:
            return num
        for i in range(min(len(need) - 1, n - 1), -1, -1):
            for d in range(int(num[i]) + 1, 10):
                tail = digits_for(need[i] // gcd(need[i], d))
                if len(tail) <= n - i - 1:
                    return num[:i] + str(d) + "1" * (n - i - 1 - len(tail)) + tail
        tail = digits_for(t)
        return "1" * max(0, n + 1 - len(tail)) + tail

