class Solution:
    def smallestPalindrome(self, s: str, k: int) -> str:
        count = Counter(s)
        half = {c: count[c] // 2 for c in sorted(count)}
        mid = "".join(c for c in count if count[c] % 2)

        def ways(total):
            res = 1
            for c in half:
                res *= comb(total, half[c])
                total -= half[c]
                if res >= k:
                    return k
            return res

        m = sum(half.values())
        if ways(m) < k:
            return ""
        left = []
        for pos in range(m):
            for c in half:
                if half[c] == 0:
                    continue
                half[c] -= 1
                w = ways(m - pos - 1)
                if w >= k:
                    left.append(c)
                    break
                k -= w
                half[c] += 1
        l = "".join(left)
        return l + mid + l[::-1]

