class Solution:
    def gcdValues(self, nums: List[int], queries: List[int]) -> List[int]:
        mx = max(nums)
        freq = [0] * (mx + 1)
        for x in nums:
            freq[x] += 1
        exact = [0] * (mx + 1)
        for d in range(mx, 0, -1):
            cnt = sum(freq[d::d])
            exact[d] = cnt * (cnt - 1) // 2
            for mult in range(2 * d, mx + 1, d):
                exact[d] -= exact[mult]
        prefix = list(itertools.accumulate(exact))
        return [bisect_right(prefix, q) for q in queries]

