    def strongPasswordChecker(self, password: str) -> int:
        n = len(password)
        missing = 3 - (any(c.islower() for c in password) + any(c.isupper() for c in password) + any(c.isdigit() for c in password))
        replace = 0
        mod = [0, 0, 0]
        i = 0
        while i < n:
            j = i
            while j < n and password[j] == password[i]:
                j += 1
            run = j - i
            if run >= 3:
                replace += run // 3
                mod[run % 3] += 1
            i = j
        if n < 6:
            return max(6 - n, missing)
        if n <= 20:
            return max(replace, missing)
        delete = n - 20
        use = min(delete, mod[0])
        replace -= use
        left = delete - use
        use = min(left, mod[1] * 2)
        replace -= use // 2
        left -= use
        replace -= left // 3
        return delete + max(replace, missing)

