class Solution:
    def wiggleSort(self, nums: List[int]) -> None:
        cnt = collections.Counter(nums)
        n, path = len(nums), []
        def bt():
            if len(path) == n:
                return True
            for v in sorted(cnt):
                if cnt[v] == 0:
                    continue
                if path:
                    if len(path) % 2 == 1 and not v > path[-1]:
                        continue
                    if len(path) % 2 == 0 and not v < path[-1]:
                        continue
                cnt[v] -= 1
                path.append(v)
                if bt():
                    return True
                path.pop()
                cnt[v] += 1
            return False
        bt()
        nums[:] = path

