class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> List[str]:
        words = set(wordDict)
        memo = {len(s): ['']}
        def dfs(i):
            if i in memo:
                return memo[i]
            out = []
            for j in range(i + 1, len(s) + 1):
                w = s[i:j]
                if w in words:
                    for rest in dfs(j):
                        out.append(w + (' ' + rest if rest else ''))
            memo[i] = out
            return out
        return dfs(0)

