class Solution:
    def findLadders(self, beginWord: str, endWord: str, wordList: List[str]) -> List[List[str]]:
        if endWord not in wordList:
            return []
        n = len(beginWord)
        buckets = collections.defaultdict(list)
        for w in wordList:
            for i in range(n):
                buckets[w[:i] + '*' + w[i + 1:]].append(w)
        parents = {}
        seen = {beginWord}
        layer = [beginWord]
        while layer and endWord not in parents:
            nxt = {}
            for w in layer:
                for i in range(n):
                    for cand in buckets.get(w[:i] + '*' + w[i + 1:], []):
                        if cand not in seen:
                            nxt.setdefault(cand, []).append(w)
            seen.update(nxt)
            parents.update(nxt)
            layer = list(nxt)
        res = []
        def build(w, path):
            if w == beginWord:
                res.append(path[::-1])
                return
            for p in parents[w]:
                build(p, path + [p])
        if endWord in parents:
            build(endWord, [endWord])
        return res

