    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        diff = [0] * (n + 1)
        cur = k = 0
        for i in range(n):
            while cur + diff[i] < nums[i]:
                if k == len(queries):
                    return -1
                l, r, v = queries[k]
                k += 1
                if r >= i:
                    diff[max(l, i)] += v
                    diff[r + 1] -= v
            cur += diff[i]
        return k

