class Solution:
    def isThereAPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        if (m + n - 1) % 2:
            return False
        lo = [[0] * n for _ in range(m)]
        hi = [[0] * n for _ in range(m)]
        for r in range(m):
            for c in range(n):
                if r == 0 and c > 0:
                    lo[r][c], hi[r][c] = lo[r][c - 1], hi[r][c - 1]
                elif c == 0 and r > 0:
                    lo[r][c], hi[r][c] = lo[r - 1][c], hi[r - 1][c]
                elif r > 0:
                    lo[r][c] = min(lo[r - 1][c], lo[r][c - 1])
                    hi[r][c] = max(hi[r - 1][c], hi[r][c - 1])
                lo[r][c] += grid[r][c]
                hi[r][c] += grid[r][c]
        target = (m + n - 1) // 2
        return lo[-1][-1] <= target <= hi[-1][-1]

