class Excel:
    def __init__(self, height: int, width: str):
        cols = ord(width) - ord('A') + 1
        self.vals = [[0] * cols for _ in range(height)]
        self.formulas = {}

    def set(self, row: int, column: str, val: int) -> None:
        cell = (row - 1, ord(column) - ord('A'))
        self.formulas.pop(cell, None)
        self.vals[cell[0]][cell[1]] = val

    def get(self, row: int, column: str) -> int:
        return self.evaluate((row - 1, ord(column) - ord('A')))

    def evaluate(self, cell):
        if cell not in self.formulas:
            return self.vals[cell[0]][cell[1]]
        total = 0
        for src, weight in self.formulas[cell].items():
            total += weight * self.evaluate(src)
        return total

    def sum(self, row: int, column: str, numbers: List[str]) -> int:
        weights = collections.Counter()
        for token in numbers:
            first, _, last = token.partition(':')
            last = last or first
            r1, c1 = int(first[1:]) - 1, ord(first[0]) - ord('A')
            r2, c2 = int(last[1:]) - 1, ord(last[0]) - ord('A')
            for r in range(r1, r2 + 1):
                for c in range(c1, c2 + 1):
                    weights[(r, c)] += 1
        cell = (row - 1, ord(column) - ord('A'))
        self.formulas[cell] = weights
        return self.evaluate(cell)

