class Solution:
    def employeeFreeTime(self, schedule: List[List[List[int]]]) -> List[List[int]]:
        heap = [(emp[0][0], i, 0) for i, emp in enumerate(schedule) if emp]
        heapq.heapify(heap)
        if not heap:
            return []
        free, prev_end = [], heap[0][0]
        while heap:
            start, i, j = heapq.heappop(heap)
            if start > prev_end:
                free.append([prev_end, start])
            prev_end = max(prev_end, schedule[i][j][1])
            if j + 1 < len(schedule[i]):
                heapq.heappush(heap, (schedule[i][j + 1][0], i, j + 1))
        return free

