    def findLeaves(self, root: Optional[TreeNode]) -> List[List[int]]:
        result = []

        def prune(node, layer):
            if not node:
                return None
            if not node.left and not node.right:
                layer.append(node.val)
                return None
            node.left = prune(node.left, layer)
            node.right = prune(node.right, layer)
            return node

        while root:
            layer = []
            root = prune(root, layer)
            result.append(layer)
        return result

