class Codec:
    def serialize(self, root: 'Node') -> str:
        if not root:
            return ""
        return str(root.val) + "[" + ",".join(self.serialize(c) for c in root.children) + "]"

    def deserialize(self, data: str) -> 'Node':
        if not data:
            return None
        k = data.index("[")
        node = Node(int(data[:k]), [])
        body = data[k + 1:-1]
        depth, start = 0, 0
        for p, ch in enumerate(body):
            if ch == "[":
                depth += 1
            elif ch == "]":
                depth -= 1
            elif ch == "," and depth == 0:
                node.children.append(self.deserialize(body[start:p]))
                start = p + 1
        if body:
            node.children.append(self.deserialize(body[start:]))
        return node

