class Solution:
    def shortestDistance(self, grid: List[List[int]]) -> int:
        R, C = len(grid), len(grid[0])
        dist = [[0] * C for _ in range(R)]
        reach = [[0] * C for _ in range(R)]
        houses = 0
        for r in range(R):
            for c in range(C):
                if grid[r][c] != 1:
                    continue
                houses += 1
                q = collections.deque([(r, c, 0)])
                seen = {(r, c)}
                while q:
                    x, y, d = q.popleft()
                    for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                        if 0 <= nx < R and 0 <= ny < C and grid[nx][ny] == 0 and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            dist[nx][ny] += d + 1
                            reach[nx][ny] += 1
                            q.append((nx, ny, d + 1))
        cells = [dist[r][c] for r in range(R) for c in range(C) if grid[r][c] == 0 and reach[r][c] == houses]
        return min(cells) if cells else -1

