class Solution:
    def maxProduct(self, s: str) -> int:
        n = len(s)
        memo = {}
        def lps(m):
            if m & (m - 1) == 0:
                return 1 if m else 0
            if m in memo:
                return memo[m]
            lo = (m & -m).bit_length() - 1
            hi = m.bit_length() - 1
            if s[lo] == s[hi]:
                res = 2 + lps(m ^ (1 << lo) ^ (1 << hi))
            else:
                res = max(lps(m ^ (1 << lo)), lps(m ^ (1 << hi)))
            memo[m] = res
            return res

        full = (1 << n) - 1
        return max(lps(m) * lps(full ^ m) for m in range(1, full))

