        self.locked[num] = None
        return True

    def upgrade(self, num: int, user: int) -> bool:
        cur = num
        while cur != -1:
            if self.locked[cur]:
                return False
            cur = self.parent[cur]

        locked_count = 0
        q = deque([num])
        while q:
            node = q.popleft()
            if self.locked[node]:
                self.locked[node] = None
                locked_count += 1
            q.extend(self.child[node])

        if locked_count > 0:
            self.locked[num] = user
