        def backtrack(n):
            if n in dp:
                return dp[n]
            res = []
            for l in range(1, n, 2):
                r = n - 1 - l
                leftTrees, rightTrees = backtrack(l), backtrack(r)
                for t1 in leftTrees:
                    for t2 in rightTrees:
