    def longestStrChain(self, words: List[str]) -> int:
        # 1. Sort words by length so shorter words are processed first
        words.sort(key=len)

        chain_length = {}
        best = 1

        for word in words:
            # 2. Start by assuming this word is a chain of length 1
            chain_length[word] = 1

            # 3. Try deleting each letter to form a candidate predecessor
            for i in range(len(word)):
                predecessor = word[:i] + word[i+1:]
                if predecessor in chain_length:
                    candidate_length = chain_length[predecessor] + 1
                    if candidate_length > chain_length[word]:
                        chain_length[word] = candidate_length

            # 4. Track the best chain length seen so far
            if chain_length[word] > best:
                best = chain_length[word]

        return best

