class Solution:
    def jobScheduling(self, startTime, endTime, profit):
        jobs = sorted(zip(endTime, startTime, profit))
        n = len(jobs)
        dp = [0] * (n + 1)
        for i in range(n):
            e, s, p = jobs[i]
            best = dp[i]
            take = p
            for j in range(i - 1, -1, -1):
                if jobs[j][0] <= s:
                    take += dp[j + 1]
                    break
            dp[i + 1] = max(best, take)
        return dp[n]

