            visited = set([start])
            stack = [start]
            while stack:
                i = stack.pop()
                xi, yi, ri = bombs[i]
                for j in range(n):
                    if j in visited:
                        continue
                    xj, yj, _ = bombs[j]
                    dist = math.sqrt((xi - xj) ** 2 + (yi - yj) ** 2)
                    if dist <= ri:
                        visited.add(j)
                        stack.append(j)
