class Solution:
    def maximumDetonation(self, bombs: List[List[int]]) -> int:
        n = len(bombs)
        graph = [[] for _ in range(n)]

        for i in range(n):
            xi, yi, r_i = bombs[i]
            for j in range(n):
                if i == j:
                    continue
                xj, yj, _ = bombs[j]
                dist_sq = (xi - xj) ** 2 + (yi - yj) ** 2
                if dist_sq <= r_i * r_i:
                    graph[i].append(j)

        best = 1
        for start in range(n):
            visited = {start}
            queue = deque([start])
            while queue:
                i = queue.popleft()
                for j in graph[i]:
                    if j not in visited:
                        visited.add(j)
                        queue.append(j)
            best = max(best, len(visited))

        return best

