class Solution:
    def rearrangeBarcodes(self, barcodes: List[int]) -> List[int]:
        n = len(barcodes)
        used = [False] * n
        result = []
        def backtrack():
            if len(result) == n:
                return True
            for i in range(n):
                if not used[i] and (not result or result[-1] != barcodes[i]):
                    result.append(barcodes[i])
                    used[i] = True
                    if backtrack():
                        return True
                    result.pop()
                    used[i] = False
            return False
        backtrack()
        return result

