class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:
        # 1. Helper to compute the sum after capping every value at 'cap'
        def capped_sum(cap):
            total = 0
            for value in arr:
                if value < cap:
                    total += value
                else:
                    total += cap
            return total

        # 2. Binary search for the smallest cap whose sum is at least target
        left = 0
        right = max(arr)
        while left < right:
            mid = (left + right) // 2
            current_sum = capped_sum(mid)
            if current_sum < target:
                left = mid + 1
            else:
                right = mid

        # 3. Compare the found cap with one less than it
        diff_lower = abs(capped_sum(left - 1) - target)
        diff_found = abs(capped_sum(left) - target)

        # 4. Prefer the smaller value on a tie
        if diff_lower <= diff_found:
            return left - 1
        return left

