class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:
        lo, hi = 0, max(arr)

        def total_sum(v):
            return sum(min(x, v) for x in arr)

        while lo < hi:
            mid = (lo + hi) // 2
            total = sum(min(x, mid) for x in arr)
            if total < target:
                lo = mid + 1
            else:
                hi = mid

        if abs(total_sum(lo - 1) - target) <= abs(total_sum(lo) - target):
            return lo - 1
        return lo

