class Solution:
    def isPossibleDivide(self, nums: List[int], k: int) -> bool:
        if len(nums) % k != 0:
            return False

        count = Counter(nums)

        for num in sorted(count):
            c = count[num]
            if c > 0:
                for i in range(num, num + k):
                    if count[i] < c:
                        return False
                    count[i] -= c

        return True

