class Solution:
    def expressiveWords(self, s: str, words: List[str]) -> int:
        n = len(s)
        def groups(string):
            res = []
            i = 0
            while i < len(string):
                j = i
                while j < len(string) and string[j] == string[i]:
                    j += 1
                res.append([string[i], j - i])
                i = j
            return res

        def canMake(wGroups, idx, built):
            if idx == len(wGroups):
                return built == s
            c, cnt = wGroups[idx]
            for extra in range(0, n - len(built) + 1):
                newCnt = cnt + extra
                if newCnt != cnt and newCnt < 3:
                    continue
                candidate = built + c * newCnt
                if len(candidate) > n:
                    break
                if canMake(wGroups, idx + 1, candidate):
                    return True
            return False

        count = 0
        for w in words:
            wGroups = groups(w)
            if canMake(wGroups, 0, ""):
                count += 1
        return count

