class Solution:
    def expressiveWords(self, s: str, words: List[str]) -> int:
        def getGroups(string):
            groups = []
            i = 0
            n = len(string)
            while i < n:
                j = i
                while j < n and string[j] == string[i]:
                    j += 1
                groups.append((string[i], j - i))
                i = j
            return groups

        sGroups = getGroups(s)
        count = 0

        for w in words:
            wGroups = getGroups(w)
            if len(wGroups) != len(sGroups):
                continue

            ok = True
            for (c1, n1), (c2, n2) in zip(sGroups, wGroups):
                if c1 != c2:
                    ok = False
                    break
                if n1 != n2 and (n1 < n2 or n1 < 3):
                    ok = False
                    break

            if ok:
                count += 1

        return count

