class Solution:
    def closedIsland(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        cols = len(grid[0])

        def flood_fill(row, col):
            if row < 0 or row >= rows or col < 0 or col >= cols:
                return
            if grid[row][col] == 1:
                return
            grid[row][col] = 1
            flood_fill(row + 1, col)
            flood_fill(row - 1, col)
            flood_fill(row, col + 1)
            flood_fill(row, col - 1)

        # 1. Drown any island that touches the border, since it can never be closed
        for row in range(rows):
            for col in range(cols):
                on_border = row == 0 or row == rows - 1 or col == 0 or col == cols - 1
                if on_border and grid[row][col] == 0:
                    flood_fill(row, col)

        # 2. Only interior cells can now form closed islands
        count = 0
        for row in range(1, rows - 1):
            for col in range(1, cols - 1):
                # 3. Each remaining land cell starts a brand new closed island
                if grid[row][col] == 0:
                    count += 1
                    # 4. Flood fill it away so we do not count it again
                    flood_fill(row, col)

        return count

