from collections import deque

class HitCounter:
    def __init__(self):
        # 1. Queue of hit timestamps, oldest at the front
        self.hits = deque()

    def hit(self, timestamp: int) -> None:
        # 2. Record this hit
        self.hits.append(timestamp)

    def getHits(self, timestamp: int) -> int:
        # 3. Drop anything outside the 300 second window
        while self.hits and self.hits[0] <= timestamp - 300:
            self.hits.popleft()

        # 4. Whatever remains is within the window
        return len(self.hits)

