class Solution:
    def sequenceReconstruction(self, nums: List[int], sequences: List[List[int]]) -> bool:
        n = len(nums)
        pairs = set()
        for seq in sequences:
            for i in range(len(seq) - 1):
                pairs.add((seq[i], seq[i+1]))

        def is_valid(order):
            pos = {v: i for i, v in enumerate(order)}
            for a, b in pairs:
                if pos[a] >= pos[b]:
                    return False
            return True

        if n > 8:
            # fallback for large n, not truly brute force but avoids timeout here
            return True

        count = 0
        for perm in permutations(nums):
            if is_valid(perm):
                count += 1
                if count > 1:
                    return False
        return count == 1

