from collections import deque
from typing import List

class Solution:
    def sequenceReconstruction(self, nums: List[int], sequences: List[List[int]]) -> bool:
        n = len(nums)
        graph = [[] for _ in range(n + 1)]
        in_degree = [0] * (n + 1)
        seen = set()

        # 1. Build adjacency list and in degree counts from consecutive pairs in each sequence
        for seq in sequences:
            for value in seq:
                seen.add(value)
            for i in range(len(seq) - 1):
                first = seq[i]
                second = seq[i + 1]
                graph[first].append(second)
                in_degree[second] += 1

        if len(seen) != n:
            return False

        # 2. Start a queue with all nodes of in degree zero
        queue = deque()
        for value in range(1, n + 1):
            if in_degree[value] == 0:
                queue.append(value)

        index = 0

        while queue:
            # 3. If the queue has more than one node, the order is ambiguous
            if len(queue) > 1:
                return False

            # 4. Pop the single node, check it matches the expected position in nums
            node = queue.popleft()
            if index >= n or node != nums[index]:
                return False
            index += 1

            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        return index == n

