from collections import deque
from typing import List

class Solution:
    def sequenceReconstruction(self, nums: List[int], sequences: List[List[int]]) -> bool:
        n = len(nums)
        graph = [[] for _ in range(n + 1)]
        indegree = [0] * (n + 1)
        seen = set()

        for seq in sequences:
            for v in seq:
                seen.add(v)
            for i in range(len(seq) - 1):
                a, b = seq[i], seq[i+1]
                graph[a].append(b)
                indegree[b] += 1

        if len(seen) != n:
            return False

        queue = deque([v for v in range(1, n + 1) if indegree[v] == 0])
        idx = 0

        while queue:
            if len(queue) > 1:
                return False
            node = queue.popleft()
            if idx >= n or node != nums[idx]:
                return False
            idx += 1
            for nxt in graph[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    queue.append(nxt)

        return idx == n

