class Sea:
    def __init__(self, ships):
        self.ships = ships

    def hasShips(self, topRight, bottomLeft):
        for x, y in self.ships:
            if bottomLeft[0] <= x <= topRight[0] and bottomLeft[1] <= y <= topRight[1]:
                return True
        return False


class Solution:
    def countShips(self, ships, topRight: list, bottomLeft: list) -> int:
        sea = Sea(ships)

        def helper(topRight, bottomLeft):
            left = bottomLeft[0]
            bottom = bottomLeft[1]
            right = topRight[0]
            top = topRight[1]

            # 1. If the rectangle is invalid or has no ships, stop
            if left > right or bottom > top:
                return 0

            if not sea.hasShips(topRight, bottomLeft):
                return 0

            # 2. If it's a single point, that point is a ship
            if left == right and bottom == top:
                return 1

            # 3. Split into four quadrants around the midpoint
            midX = (left + right) // 2
            midY = (bottom + top) // 2

            count = 0
            count += helper([midX, midY], [left, bottom])
            count += helper([right, midY], [midX + 1, bottom])
            count += helper([midX, top], [left, midY + 1])
            count += helper([right, top], [midX + 1, midY + 1])

            # 4. Sum the counts from each quadrant
            return count

        return helper(topRight, bottomLeft)

