        self.ships = ships
    def hasShips(self, topRight, bottomLeft):
        for x, y in self.ships:
            if bottomLeft[0] <= x <= topRight[0] and bottomLeft[1] <= y <= topRight[1]:
                return True
        return False

class Solution:
    def countShips(self, ans, topRight: list, bottomLeft: list) -> int:
        sea = Sea(ans)

        def helper(topRight, bottomLeft):
            x1, y1 = topRight
            x2, y2 = bottomLeft

            if x2 > x1 or y2 > y1:
                return 0

            if not sea.hasShips(topRight, bottomLeft):
                return 0

            if topRight == bottomLeft:
                return 1

            midx = (x1 + x2) // 2
            midy = (y1 + y2) // 2

            count = 0
            count += helper([midx, midy], [x2, y2])
            count += helper([x1, midy], [midx + 1, y2])
            count += helper([midx, y1], [x2, midy + 1])
            count += helper([x1, y1], [midx + 1, midy + 1])
            return count

        return helper(topRight, bottomLeft)
